export function resolveCategoryName(item, itemCategories = []) {
  if (!item) return 'Mechanical';

  const rawCatVal = typeof item === 'string' ? item : (item.work_main_category || item.main_category);

  // 0. If rawCatVal maps to a specific non-generic BOQ Work Type via UUID or exact name, respect it first
  if (rawCatVal && STATIC_CATEGORIES_LOOKUP[rawCatVal]) {
    const mapped = STATIC_CATEGORIES_LOOKUP[rawCatVal];
    if (mapped !== 'Mechanical' && mapped !== 'Electrical') {
      return mapped;
    }
  }
  if (rawCatVal && OFFICIAL_BOQ_WORK_TYPES_SET.has(rawCatVal) && rawCatVal !== 'Mechanical' && rawCatVal !== 'Electrical') {
    return rawCatVal;
  }

  // 1. High Priority: Classify directly from _spawnerid or item details to official database BOQ Work Types
  if (typeof item === 'object' && item !== null) {
    const sp = String(item._spawnerid || item._spawnerId || '').toLowerCase();
    const resolvedItemName = item.item_name || (item.item && STATIC_ITEMS_LOOKUP[item.item]) || item.item || '';
    const nameStr = String(resolvedItemName).toLowerCase();
    const rawCat = String(item.work_main_category || item.main_category || '').toLowerCase();

    // Specific Pump Electrical Connection Spawners -> Electrical
    if (
      sp.startsWith('_isem_filtration_pump_') ||
      sp.startsWith('_isem_vacuum_pump_') ||
      sp.startsWith('_isem_submersible_pump_') ||
      sp.includes('wfelecinstallation') ||
      sp.includes('electricalworksinstallation') ||
      sp.includes('elecaccom')
    ) {
      return 'Electrical';
    }

    // Specific Electrical Trade Categories
    if (sp.includes('panel') || nameStr.includes('control panel') || rawCat.includes('control panel')) return 'Control Panel';
    if (sp.includes('earth') || sp.includes('thermoweld') || sp.includes('cabletosteel') || sp.includes('drivingstud') || sp.includes('earthpit') || sp.includes('barecopper') || nameStr.includes('earth') || nameStr.includes('grounding')) return 'Water Feature Earthing';
    if (sp.includes('cabletray') || sp.includes('spliceplate') || sp.includes('velbow') || sp.includes('helbow') || sp.includes('endcap') || sp.includes('cchannel') || sp.includes('anchorsauto') || nameStr.includes('cable tray')) return 'Main Cable Tray';
    if (sp.includes('prlight') || sp.includes('prswitch') || sp.includes('prenclosure') || sp.includes('prmtcoupler') || sp.includes('prmtgland') || sp.includes('prmtstrap') || sp.includes('prmtadapter') || nameStr.includes('pump room light')) return 'Pump Room Lighting';
    if (sp.includes('socket') || sp.includes('prsocket') || nameStr.includes('socket')) return 'Service Sockets';
    if (
      sp.includes('transformer') || sp.includes('transjbox') || sp.includes('jboxauto') ||
      sp.includes('feedingcable') || sp.includes('outputcable') || sp.includes('electriccable') ||
      sp.includes('cableglandauto') || sp.includes('protectiveconduit') || sp.includes('mainconduit') ||
      (sp.includes('light') && !sp.includes('prlight')) ||
      nameStr.includes('underwater light') || nameStr.includes('lighting fixture') || nameStr.includes('transformer')
    ) {
      return 'Water Feature Lighting';
    }

    if (rawCat.includes('electrical') || nameStr.includes('cable') || nameStr.includes('disconnect switch')) {
      return 'Electrical';
    }

    // Mechanical Trade
    if (sp.includes('filtration_pump') || sp.includes('filterpump') || nameStr.includes('filtration pump')) return 'Water Filtration Pump';
    if (sp.includes('vacuum_pump') || sp.includes('vacuumpump') || nameStr.includes('vacuum pump')) return 'Vacuum Filtration Pump';
    if (sp.includes('submersible') || nameStr.includes('submersible pump')) return 'Submersible Pumps';
    if (sp.includes('sandfilter') || (sp.includes('filter') && !sp.includes('vacuum')) || nameStr.includes('sand filter')) return 'Water Filter';
    if (sp.includes('vacuumfilter') || nameStr.includes('vacuum filter')) return 'Vacuum Filter';
    if (sp.includes('prupvc') || sp.includes('prballvalve') || sp.includes('prcheckvalve') || sp.includes('prsolenoid') || sp.includes('prnonreturn') || sp.includes('valve') || nameStr.includes('valve')) return 'Pump Room UPVC Pipes, Fittings & Valves';
    if (sp.includes('upvcpipe') || sp.includes('upvctee') || sp.includes('upvcelbow') || sp.includes('upvcflange') || sp.includes('upvcred') || sp.includes('upvc')) return 'Water Feature UPVC Pipes, Fittings & Valves';
    if (sp.includes('hdpepipe') || sp.includes('hdpelbow') || sp.includes('hdpestub') || sp.includes('hdpestubflange') || sp.includes('hdpe')) return 'Water Feature HDPE Pipes, Fittings & Valves';
    if (sp.includes('chlorinator') || sp.includes('dosing') || nameStr.includes('dosing') || nameStr.includes('chlorin')) return 'Chemical Dosing System';
    if (sp.includes('tablet') || nameStr.includes('tablet chlorinator')) return 'Tablet Chlorinator';
    if (sp.includes('heater') || nameStr.includes('heater')) return 'Heating System';
    if (sp.includes('makeup') || nameStr.includes('makeup')) return 'Automatic Makeup System';
    if (sp.includes('chamber') || sp.includes('drainagechamber') || sp.includes('grpbox') || nameStr.includes('drainage chamber')) return 'Drainage Chamber';
    if (sp.includes('maindrain') || nameStr.includes('main drain')) return 'Main Drain';
    if (sp.includes('gutterdrain') || nameStr.includes('gutter drain')) return 'Gutter Drain';
    if (sp.includes('floorinlet') || nameStr.includes('floor inlet')) return 'Floor Inlets';
    if (sp.includes('wallinlet') || nameStr.includes('wall inlet')) return 'Wall Inlets';
    if (sp.includes('vacuuminlet') || sp.includes('vacuumpoint') || nameStr.includes('vacuum point') || nameStr.includes('vacuum inlet')) return 'Vacuum Points';
    if (sp.includes('skimmer') || nameStr.includes('skimmer')) return 'Skimmer';
    if (sp.includes('fan') || sp.includes('ventilation') || nameStr.includes('ventilation fan')) return 'Ventilation';
    if (sp.includes('ext') || sp.includes('fire') || nameStr.includes('fire extinguisher')) return 'Fire Extinguisher';

    // Civil Trade (check plaster before cem, and coping before tiling)
    if (sp.includes('pc') || sp.includes('plain_concrete') || nameStr.includes('plain concrete') || rawCat.includes('plain concrete')) return 'Plain Concrete';
    if (sp.includes('rc') || sp.includes('reinforced_concrete') || nameStr.includes('reinforced concrete') || rawCat.includes('reinforced concrete')) return 'Reinforced Concrete';
    if (sp.includes('coffor') || nameStr.includes('coffor') || rawCat.includes('coffor')) return 'Coffor';
    if (sp.includes('bitu') || nameStr.includes('bituminous') || rawCat.includes('bituminous')) return 'Bituminous Waterproofing';
    if (sp.includes('plaster') || sp.includes('stucco') || nameStr.includes('plaster') || rawCat.includes('plaster')) return 'Plastering Works';
    if (sp.includes('cem') || nameStr.includes('cementitious') || rawCat.includes('cementitious')) return 'Cementitious Waterproofing';
    if (sp.includes('membrane') || sp.includes('geomembrane') || nameStr.includes('geomembrane') || rawCat.includes('geomembrane')) return 'Geomembrane Works';
    if (sp.includes('coping') || nameStr.includes('coping') || rawCat.includes('coping') || rawCat.includes('copping') || nameStr.includes('sika lasqa')) return 'Copping Works';
    if (sp.includes('tiling') || sp.includes('tile') || nameStr.includes('tile') || rawCat.includes('tiling')) return 'Tiling Works';
    if (sp.includes('ladder') || nameStr.includes('ladder') || rawCat.includes('ladder')) return 'Stainless Steel Ladder';
    if (sp.includes('epoxy') || nameStr.includes('epoxy') || rawCat.includes('epoxy')) return 'Epoxy Painting';
    if (sp.includes('geonet') || nameStr.includes('geonet') || rawCat.includes('geonet')) return 'Geonets Works';
    if (sp.includes('geotextile') || nameStr.includes('geotextile') || rawCat.includes('geotextile')) return 'Geotextiles Works';
    if (sp.includes('ceramic') || nameStr.includes('ceramic') || rawCat.includes('ceramic')) return 'Ceramic Works';
    if (sp.includes('liner') || nameStr.includes('liner') || rawCat.includes('liner')) return 'Liner Works';
  }

  // 2. Direct Static Lookup by UUID
  if (rawCatVal && STATIC_CATEGORIES_LOOKUP[rawCatVal]) {
    return STATIC_CATEGORIES_LOOKUP[rawCatVal];
  }

  // 3. Lookup in item_categories list/table if passed
  if (Array.isArray(itemCategories) && itemCategories.length > 0 && rawCatVal) {
    const catObj = itemCategories.find(c => c && (String(c.id) === String(rawCatVal) || String(c.category_id) === String(rawCatVal)));
    if (catObj && (catObj.category_name || catObj.name)) {
      const name = catObj.category_name || catObj.name;
      if (OFFICIAL_BOQ_WORK_TYPES_SET.has(name)) return name;
    }
  }

  // 4. If rawCatVal is already an official human-readable BOQ Work Type
  if (rawCatVal) {
    const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(rawCatVal);
    if (!isUuid && OFFICIAL_BOQ_WORK_TYPES_SET.has(rawCatVal)) return rawCatVal;
  }

  // 5. Fallback based on work_type if present
  if (typeof item === 'object' && item !== null) {
    const wt = String(item.work_type || '').toLowerCase().trim();
    if (wt === 'civil') return 'Plain Concrete';
    if (wt === 'finishing works') return 'Plastering Works';
    if (wt === 'electrical') return 'Electrical';
  }

  return 'Mechanical';
}

