// Standard filtration method UUID for Skimfilter
export const SKIMFILTER_FILTRATION_METHOD_UUID = '4ec9604f-02b4-4540-8e1d-10c95b9f3652';

export function isWfOverflow(rawType) {
  if (!rawType) return false;
  const str = String(rawType).trim().toLowerCase();
  const resolved = (STATIC_WF_TYPES_LOOKUP[rawType] || str).toLowerCase();
  return (
    rawType === 'a8133ec0-271f-44e1-a693-c3c19efe19dc' || // Overflow UUID
    rawType === '77f528c6-88d7-4f54-a964-285666c3ac99' || // Olympic Pool UUID
    resolved.includes('overflow') ||
    resolved.includes('olympic') ||
    resolved.includes('deck slot') ||
    resolved.includes('infinity')
  );
}

export function isWfSkimmer(rawType) {
  if (!rawType) return false;
  const str = String(rawType).trim().toLowerCase();
  const resolved = (STATIC_WF_TYPES_LOOKUP[rawType] || str).toLowerCase();
  return (
    rawType === '33e2d774-7e31-49bc-8b01-4547719e233d' ||
    (resolved.includes('skimmer') && !resolved.includes('skimfilter'))
  );
}

export function isWfSkimfilter(rawType, rawMethod) {
  const typeStr = String(rawType || '').trim().toLowerCase();
  const resolvedType = (STATIC_WF_TYPES_LOOKUP[rawType] || typeStr).toLowerCase();
  const methodStr = String(rawMethod || '').trim().toLowerCase();
  return (
    rawType === 'e076f96a-8aa7-4515-a917-3e95039f2133' || // Skimfilter Type UUID
    rawMethod === SKIMFILTER_FILTRATION_METHOD_UUID ||      // Skimfilter Method UUID
    resolvedType.includes('skimfilter') ||
    methodStr.includes('skimfilter')
  );
}

export function isWfLagoon(rawCatOrType) {
  if (!rawCatOrType) return false;
  const str = String(rawCatOrType).trim().toLowerCase();
  const resolvedCat = (STATIC_WF_CATEGORIES_LOOKUP[rawCatOrType] || '').toLowerCase();
  const resolvedType = (STATIC_WF_TYPES_LOOKUP[rawCatOrType] || '').toLowerCase();
  return (
    rawCatOrType === 'b040678e-1343-4def-8fc8-2d6b5850fcbf' ||
    rawCatOrType === 'bcdbf836-1657-407a-a46c-1dab51790d02' ||
    rawCatOrType === '1657a003-b0c6-4fdc-9614-14861279dbed' ||
    resolvedCat.includes('lagoon') ||
    resolvedType.includes('lagoon') ||
    str.includes('lagoon')
  );
}

