export function resolveWaterFeatureType(pde, fallback = 'Not Specified') {
  if (!pde) return fallback;
  const rawType = pde.water_feature_type;
  if (!rawType) {
    const rawCat = pde.water_feature_category;
    if (rawCat && STATIC_WF_CATEGORIES_LOOKUP[rawCat]) return STATIC_WF_CATEGORIES_LOOKUP[rawCat];
    return fallback;
  }
  if (STATIC_WF_TYPES_LOOKUP[rawType]) return STATIC_WF_TYPES_LOOKUP[rawType];
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(rawType);
  if (!isUuid) return rawType;
  return fallback;
}

export function resolveWaterFeatureCategory(pde, fallback = 'Not Specified') {
  if (!pde) return fallback;
  const rawCat = pde.water_feature_category;
  if (!rawCat) return fallback;
  if (STATIC_WF_CATEGORIES_LOOKUP[rawCat]) return STATIC_WF_CATEGORIES_LOOKUP[rawCat];
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(rawCat);
  if (!isUuid) return rawCat;
  return fallback;
}


